}

/* ─── Reset ──────────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* ─── Base ───────────────────────────────────────────────────────────────── */
body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.65;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ─── Skip link ──────────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  padding: 0.5rem 1.25rem;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
  z-index: 200;
}
.skip-link:focus { top: 0; outline: 3px solid #fff; outline-offset: 2px; }

/* ─── Header ─────────────────────────────────────────────────────────────── */
.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 2rem 1.5rem;
}
.header-inner {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 1.25rem;
}
.header-icon { font-size: 2.5rem; line-height: 1; flex-shrink: 0; }

h1 {
  font-size: clamp(1.6rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}
.tagline { color: var(--text-muted); margin-top: 0.25rem; }

/* ─── Main ───────────────────────────────────────────────────────────────── */
main {
  flex: 1;
  max-width: 760px;
  width: 100%;
  margin: 0 auto;
  padding: 2.5rem 1.5rem;
}

.section-heading {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 1.25rem;
}

/* ─── FAQ list ───────────────────────────────────────────────────────────── */
#faq-root {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

/* ─── Disclosure widget (.example wraps each Q/A) ────────────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color 0.15s;
}
.example:has([aria-expanded="true"]) { border-color: var(--accent-dim); }

/* Heading resets */
.example h3 { margin: 0; font-size: 1rem; font-weight: normal; }

/* Trigger button */
.example h3 button {
  width: 100%;
  background: transparent;
  border: none;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.375rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  transition: background 0.12s;
}
.example h3 button:hover { background: var(--surface-hover); }
.example h3 button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: 2px;
}

/* Chevron */
.example h3 button::after {
  content: '';
  display: block;
  width: 0.55em;
  height: 0.55em;
  border-right: 2.5px solid var(--accent);
  border-bottom: 2.5px solid var(--accent);
  transform: rotate(45deg) translateY(-0.15em);
  flex-shrink: 0;
  transition: transform 0.2s ease;
}
.example h3 button[aria-expanded="true"]::after {
  transform: rotate(-135deg) translateY(-0.15em);
}

/* ─── Panel (.details holds the controlled content) ─────────────────────── */
.details {
  padding: 0 1.375rem 1.2rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}
.details p { padding-top: 1rem; }
.details p + p { margin-top: 0.75rem; }

/* ─── Footer ─────────────────────────────────────────────────────────────── */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--border);
  padding: 1.25rem 1.5rem;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* ─── Reflow (320px) ─────────────────────────────────────────────────────── */
@media (max-width: 400px) {
  .header-inner { flex-direction: column; align-items: flex-start; gap: 0.5rem; }
  .header-icon { font-size: 2rem; }
  main { padding: 1.5rem 1rem; }
  .example h3 button { padding: 1rem; }
  .details { padding: 0 1rem 1rem; }
}

/* ─── Reduced motion ─────────────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .example,
  .example h3 button,
  .example h3 button::after { transition: none; }
}

/* ─── Forced colors (Windows High Contrast) ─────────────────────────────── */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h3 button { color: ButtonText; }
  .example h3 button::after { border-color: ButtonText; }
  .example:has([aria-expanded="true"]) { border-color: Highlight; }
}
